#pragma once
#include <string>
#include <cstdint>
#include <netinet/in.h>
#include <arpa/inet.h>

class IPAddr {
public:
    virtual ~IPAddr() = default;
    virtual int Version() const = 0;
    virtual std::size_t Size() const = 0;
    virtual const sockaddr* Raw() const = 0;
    virtual std::uint16_t Port() const = 0;
    virtual std::string IPAddress() const = 0;
};

class IPv4Addr final : public IPAddr {
public:
    static constexpr int version = AF_INET;
    static constexpr std::string_view loop_back = "127.0.0.1";
    static constexpr std::string_view any = "0.0.0.0";
    static constexpr std::size_t max_length = 15;

    explicit IPv4Addr(sockaddr_in addr);
    IPv4Addr(std::string ip, std::uint16_t port);

    int Version() const override;
    std::size_t Size() const override;
    const sockaddr* Raw() const override;
    std::uint16_t Port() const override;
    std::string IPAddress() const override;

private:
    std::string ip_;
    sockaddr_in raw_;
};

class IPv6Addr final : public IPAddr {
public:
    static constexpr int version = AF_INET6;
    static constexpr std::string_view loop_back = "::1";
    static constexpr std::string_view any = "::";
    static constexpr std::size_t max_length = 45;

    explicit IPv6Addr(sockaddr_in6 addr);
    IPv6Addr(std::string ip, std::uint16_t port);

    int Version() const override;
    std::size_t Size() const override;
    const sockaddr* Raw() const override;
    std::uint16_t Port() const override;
    std::string IPAddress() const override;

private:
    std::string ip_;
    sockaddr_in6 raw_;
};

#include "ip.h"
#include "util.h"

IPv4Addr::IPv4Addr(sockaddr_in addr) : raw_(std::move(addr)) {
    char buf[INET_ADDRSTRLEN];
    if (inet_ntop(AF_INET, &raw_.sin_addr, buf, sizeof(buf)) == nullptr) {
        ThrowLastSystemError();
    }
    ip_ = buf;
}

IPv4Addr::IPv4Addr(std::string ip, std::uint16_t port) : ip_(std::move(ip)) {
    raw_.sin_family = version;
    raw_.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_.data(), &raw_.sin_addr) != 1) {
        ThrowLastSystemError();
    }
}

int IPv4Addr::Version() const { return version; }

std::size_t IPv4Addr::Size() const { return sizeof(raw_); }

const sockaddr* IPv4Addr::Raw() const { return reinterpret_cast<const sockaddr*>(&raw_); }

std::uint16_t IPv4Addr::Port() const { return ntohs(raw_.sin_port); }

std::string IPv4Addr::IPAddress() const { return ip_; }

IPv6Addr::IPv6Addr(sockaddr_in6 addr) : raw_(std::move(addr)) {
    char buf[INET6_ADDRSTRLEN];
    if (inet_ntop(AF_INET6, &raw_.sin6_addr, buf, sizeof(buf)) == nullptr) {
        ThrowLastSystemError();
    }
    ip_ = buf;
}

IPv6Addr::IPv6Addr(std::string ip, std::uint16_t port) : ip_(std::move(ip)) {
    raw_.sin6_family = version;
    raw_.sin6_port = htons(port);
    if (inet_pton(AF_INET6, ip_.data(), &raw_.sin6_addr) != 1) {
        ThrowLastSystemError();
    }
}

int IPv6Addr::Version() const { return version; }

std::size_t IPv6Addr::Size() const { return sizeof(raw_); }

const sockaddr* IPv6Addr::Raw() const { return reinterpret_cast<const sockaddr*>(&raw_); }

std::uint16_t IPv6Addr::Port() const { return ntohs(raw_.sin6_port); }

std::string IPv6Addr::IPAddress() const { return ip_; }
